INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26401, 'Acts 17:9', 'Acts', 17, 9, '&nbsp;نو هغوئ د ياسون او نورو نه ضمانت واخستلو او پرې يې ښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26402, 'Acts 17:10', 'Acts', 17, 10, '&nbsp;په هم هغه شپه ايماندارانو وروڼو پولوس او سيلاس بيريه ته ولېږل. کله چې هغوئ راورسېدل نو د يهوديانو عبادتخانې ته لاړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26403, 'Acts 17:11', 'Acts', 17, 11, '&nbsp;دا يهوديان د تِسالونيکيه د يهوديانو په نسبت آزاد خياله وو، ځکه چې هغوئ کلام ډېر په اخلاص قبول کړے وو او هره ورځ به يې د صحيفو په لوستلو غور کولو ترڅو په دې پوهه شى چې د هغوئ تعليم صحيح دے او کۀ نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26404, 'Acts 17:12', 'Acts', 17, 12, '&nbsp;نو په دې وجه په هغوئ کښې ډېرو ايمان راوړو او ورسره څۀ يونانيانې عزتمندې ښځې او سړى هم ملګرى شُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26405, 'Acts 17:13', 'Acts', 17, 13, '&nbsp;خو چې د تِسالونيکيه يهوديانو ته دا پته ولګېده چې پولوس په بيريه کښې هم د خُدائ پاک کلام بيانوى نو هغوئ هلته هم راغلل چې ګڼه د هغوئ خلاف ولمسوى او را وې پاروى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26406, 'Acts 17:14', 'Acts', 17, 14, '&nbsp;نو ايماندارانو وروڼو پولوس سمدستى ښکته ساحل ته ولېږلو. خو سيلاس او تيموتيوس دواړه وروستو پاتې شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26407, 'Acts 17:15', 'Acts', 17, 15, '&nbsp;هغه کسان چې د پولوس د لارې ملګرى وُو نو هغه يې اتينيه ته راوستو او په واپسۍ کښې يې سيلاس او تيموتيوس ته دا پېغام ورکړو، څومره زر چې کېدے شى ما ته خپل ځان راورسوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26408, 'Acts 17:16', 'Acts', 17, 16, '&nbsp;بيا چې پولوس په اتينيه کښې د هغوئ په اِنتظار وو نو زړۀ يې ډېر غمژن شو چې ښار يې له بُتانو نه ډک وليدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26409, 'Acts 17:17', 'Acts', 17, 17, '&nbsp;نو هغۀ به په عبادتخانه کښې د يهوديانو او دينداره يونانيانو سره بحثونه کول او دغسې به يې په بازارونو کښې هره ورځ هغوئ سره کول څوک چې به هلته وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26410, 'Acts 17:18', 'Acts', 17, 18, '&nbsp;ځينې اِپيکورى او ستُوئيکى فلسفيانو هم ورسره بحث وکړو او ځينو ووئيل چې، ”دا بکواس کولو والا څۀ وئيل غواړى؟“ او نورو ووئيل چې، ”داسې لګى چې دے د غېرو معبودانو بيان کوى.“ او دا يې ځکه ووئيل چې هغۀ د عيسىٰ او د قيامت په حقله زيرے اورولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26411, 'Acts 17:19', 'Acts', 17, 19, '&nbsp;نو هغوئ هغه ونيولو او اريوپاګوس دربار ته يې راوستو او ورته يې ووئيل چې، ”دا نوے تعليم کوم چې تۀ ورکوې، مونږ په دې پوهولے شې څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26412, 'Acts 17:20', 'Acts', 17, 20, '&nbsp;مونږ ته تۀ څۀ عجيبه بيانونه رارسوې، خو مونږ په دې ځان پوهول غواړو چې د دې مطلب څۀ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26413, 'Acts 17:21', 'Acts', 17, 21, '&nbsp;نو په هغه وخت کښې اتينيانو او د هغه ځائ بهرنى خلقو سره په نوې سوچونو باندې د تاويلو ماويلو نه بغېر بله مشغولا نۀ وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26414, 'Acts 17:22', 'Acts', 17, 22, '&nbsp;نو بيا پولوس د اريوپاګوس د دربار په وړاندې ودرېدو او وې وئيل چې، ”اے اتينيانو، زۀ وينم چې تاسو په هر لحاظ ډېر سرګرم ايمانداران يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26415, 'Acts 17:23', 'Acts', 17, 23, '&nbsp;ځکه هر کله چې زۀ په ښار کښې وګرځېدم او ما ستاسو د عبادت د څيزونو ننداره په غور سره وکړه نو ما د نورو څيزونو سره يوه قربان‌ګاه وليدله چې دا پرې ليکلے شوى وُو چې، د نامعلومه خُدائ پاک دپاره. تاسو چې د کوم څيز د نامعلوم په طور عبادت کوئ، هم دغه څيز زۀ درته بيانوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26416, 'Acts 17:24', 'Acts', 17, 24, '&nbsp;هغه خُدائ پاک چې دُنيا يې پېدا کړه او په کښې يې هر څيز هم پېدا کړل، څوک چې د آسمان او د زمکې مالِک دے هغه د بنى آدمو د لاس جوړو شوو زيارتونو کښې نۀ اوسيږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26417, 'Acts 17:25', 'Acts', 17, 25, '&nbsp;نۀ د بنى آدم لاس د هغۀ خِدمت کولے شى او نۀ هغه د بنى آدم د څۀ څيز محتاج دے، بلکې هغه په خپله ټولو بنى آدمو له ژوند، ساه او هر څۀ ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26418, 'Acts 17:26', 'Acts', 17, 26, '&nbsp;هغۀ د دُنيا ټول قومونه چې د دُنيا په مخ اوسيږى د يو انسان نه پېدا کړى دى. هغۀ د هغوئ ميعادونه او د اوسېدو حدونه مقرر کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26419, 'Acts 17:27', 'Acts', 17, 27, '&nbsp;نو د هغۀ غرض دا وو چې دوئ د خُدائ پاک لټون وکړى او کېدے شى چې په لټولو يې بيامومئ. بې‌شکه چې هغه زمونږ د چا نه هم لرې نۀ دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26420, 'Acts 17:28', 'Acts', 17, 28, '&nbsp;ځکه چې په هغۀ کښې زمونږ ژوندون، حرکت او وجود دے. لکه څنګه چې ستاسو خپلو ځينو شاعرانو وئيلى دى، مونږ هم د هغۀ د نسل نه يُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26421, 'Acts 17:29', 'Acts', 17, 29, '&nbsp;نو چې مونږ د خُدائ پاک اولاد يُو نو بيا مونږ ته دا سوچ کول مناسب نۀ دى چې د خُدائ ذات لکه د سرو زرو، د سپينو زرو يا د کاڼى د بُت په شان وګڼو چې بنى آدم په خپله پوهه او هُنر سره جوړ کړى وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26422, 'Acts 17:30', 'Acts', 17, 30, '&nbsp;په تير وختونو کښې خُدائ پاک دا جهالت نظر انداز کړے وو خو اوس هغه هر چرته ټولو بنى آدمو له حُکم ورکوى چې توبه ګار شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26423, 'Acts 17:31', 'Acts', 17, 31, '&nbsp;ځکه چې هغۀ يوه ورځ مقرره کړې ده په کومه چې به هغه د دُنيا عدالت په صداقت سره د يو سړى په وسيله وکړى کوم چې هغۀ غوره کړے دے، او ټولو ته د دې ثبوت ورکولو دپاره چې هغه څوک دے چې د مړو نه يې بيا راژوندے کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26424, 'Acts 17:32', 'Acts', 17, 32, '&nbsp;کله چې هغوئ د مړو نه د بيا راژوندى کولو خبرې واورېدلې نو ځينو ورپورې ټوقې شروع کړې خو نورو ورته ووئيل چې، ”په دې حقله به مونږ تا نه بيا خبرې واورو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26425, 'Acts 17:33', 'Acts', 17, 33, '&nbsp;نو دغه شان پولوس د خلقو د مينځ نه ووتو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26426, 'Acts 17:34', 'Acts', 17, 34, '&nbsp;خو يو څو کسان ورسره شول او ايمان يې راوړو چې په هغوئ کښې يو ديونيسيوس د اريوپاګوس د دربار کس وو او ورسره دمريس نومې يوه ښځه او ځينې نور کسان هم وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26427, 'Acts 18:1', 'Acts', 18, 1, '&nbsp;د دې نه پس پولوس د اتينيه نه روان شو او کورنتوس ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26428, 'Acts 18:2', 'Acts', 18, 2, '&nbsp;هلته هغه اکوله نومې يهودى سره مِلاو شو چې د اصل نه د پونطوس وو او د ښځې نوم يې پرسکله وه. هغه تازه تازه د اِټلى نه راغلے وو ځکه چې کلوديوس ټولو يهوديانو ته حُکم ورکړے وو چې د روم نه ووځئ. پولوس هغوئ سره د مِلاوېدو دپاره ورغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26429, 'Acts 18:3', 'Acts', 18, 3, '&nbsp;پولوس هلته ورسره اوسېدلو او دوئ سره يې يو ځائ کار کولو ځکه چې د دوئ هم د هغۀ په شان د تمبوانو جوړولو کسب وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26430, 'Acts 18:4', 'Acts', 18, 4, '&nbsp;هغۀ به د هر سبت په ورځ د يهوديانو په عبادتخانې کښې بحث مباحثه کوله او د هغۀ کوشش دا وو چې يهوديان او يونانيان خپل ځان ته راواړوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26431, 'Acts 18:5', 'Acts', 18, 5, '&nbsp;کله چې سيلاس او تيموتيوس د مِکدونيه نه راورسېدل نو پولوس خپل ځان په پوره توګه د تعليم دپاره وقف کړو او يهوديانو ته يې دا ګواهى ورکړه چې عيسىٰ هم مسيح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26432, 'Acts 18:6', 'Acts', 18, 6, '&nbsp;خو چې کله يې هغوئ مخالفت وکړو او بدرد يې ورته ووئيل نو هغۀ احتجاجاً خپلې جامې وڅنډلې او هغوئ ته يې ووئيل چې، ”ستاسو خون ستاسو په غاړه، زۀ ترې پاک يم. اوس به زۀ غېر‌يهوديانو ته لاړ شم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26433, 'Acts 18:7', 'Acts', 18, 7, '&nbsp;بيا هغه د عبادتخانې نه روان شو او د تيطيوس يوستوس نومې سړى کور ته لاړو چې د خُدائ پاک عبادت کوونکے وو او کور يې د عبادتخانې سره نزدې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26434, 'Acts 18:8', 'Acts', 18, 8, '&nbsp;کرسپوس چې د عبادتخانې مشر وو سره د خپل مکمل خاندان په مالِک ايمان راوړو، او ډېرو کورنتيانو چا چې د پولوس تعليم واورېدو ايمان يې راوړو او بپتسمه ورته ورکړے شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26435, 'Acts 18:9', 'Acts', 18, 9, '&nbsp;يوه شپه پولوس ته مالِک په رويا کښې وفرمائيل چې، ”يرېږه مه، خپل تبليغ جارى ساته او خاموشه کېږه مه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26436, 'Acts 18:10', 'Acts', 18, 10, '&nbsp;ځکه چې زۀ درسره يم. او هيڅوک به درباندې د نقصان رسولو دپاره حمله ونۀ کړى ځکه چې په دې ښار کښې ډېر خلق داسې دى چې زما دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26437, 'Acts 18:11', 'Acts', 18, 11, '&nbsp;نو هغه هلته يو کال او شپږ مياشتې پاتې شو او هغوئ ته يې د خُدائ پاک د کلام تعليم ورکولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26438, 'Acts 18:12', 'Acts', 18, 12, '&nbsp;خو چې کله ګليو د اخيه حاکِم شو نو يهوديانو په شريکه په پولوس حمله وکړه او هغه يې عدالت ته پېش کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26439, 'Acts 18:13', 'Acts', 18, 13, '&nbsp;هغوئ ووئيل چې، ”دغه سړے په داسې طريقه خلق د خُدائ پاک عبادت ته راړوى چې د شريعت خلاف ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26440, 'Acts 18:14', 'Acts', 18, 14, '&nbsp;څنګه چې پولوس جواب ورکولو نو په دې کښې ګليو يهوديانو ته ووئيل چې، ”کۀ چرې دا خبره د جرم يا د سخت شرارت وى نو يهوديانو، ما به ستاسو شکايت مناسب ګڼلے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26441, 'Acts 18:15', 'Acts', 18, 15, '&nbsp;خو چې دا ستاسو د لفظونو، نومونو او د يهودى شريعت خبره ده، نو بيا تاسو په خپله ورسره پوهه شئ، زۀ د داسې مسئلو منصف جوړېدل نۀ غواړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26442, 'Acts 18:16', 'Acts', 18, 16, '&nbsp;او هغۀ هغوئ د عدالت نه وشړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26443, 'Acts 18:17', 'Acts', 18, 17, '&nbsp;بيا هغوئ ټولو سوستينس راونيولو څوک چې د عبادتخانې سردار وو او هغه يې د عدالت په وړاندې ووهلو. خو ګليو په دې کار هيڅ غوږ ونۀ ګرولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26444, 'Acts 18:18', 'Acts', 18, 18, '&nbsp;پولوس د څۀ وخت دپاره هلته پاتې شو، بيا يې ايماندارانو وروڼو نه رُخصت واخستو او په سمندرى جهاز کښې شام ته روان شو او ورسره پرسکله او اکوله هم وُو. نو په کِنخريه کښې هغۀ خپل سر وخرېلو ځکه چې هغۀ منښته کړې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26445, 'Acts 18:19', 'Acts', 18, 19, '&nbsp;کله چې هغوئ اِفِسوس ته ورسېدل نو پولوس پرسکله او اکوله هلته پرېښودل. خو کله چې هغه هلته وو نو په عبادتخانه کښې يې د يهوديانو سره مناظره وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
