(26457, 'Acts 19:3', 'Acts', 19, 3, '&nbsp;بيا پولوس ووئيل چې، ”تاسو ته د څۀ بپتسمه درکړے شوې وه؟“ هغوئ جواب ورکړو چې، ”د يحيىٰ بپتسمه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
